namespace Tripous.Data;

/// <summary>
/// Coordinates database operations for a list table and an item table tree.
/// Tables managed by a TableSet use a single-field primary key: either a string
/// containing a GUID or an integer generated by an auto-increment column or a
/// database generator/sequence. These conventions apply to TableSet operations;
/// other database access mechanisms may use different kinds of keys.
/// </summary>
public class TableSet
{
    // ● private fields
    readonly SqlStore fStore;
    readonly MemTable fListTable;
    readonly MemTable fItemTable;
    readonly TableSetFlags fFlags;

    // ● private
    void PrepareListSaveSql(bool HasDeletes, bool HasUpdates, bool HasInserts)
    {
        bool Missing = (HasDeletes && string.IsNullOrWhiteSpace(fListTable.Sqls.DeleteRowSql))
            || (HasUpdates && string.IsNullOrWhiteSpace(fListTable.Sqls.UpdateRowSql))
            || (HasInserts && string.IsNullOrWhiteSpace(fListTable.Sqls.InsertRowSql));
        if (Missing && (fFlags & TableSetFlags.GenerateSql) != 0)
        {
            DbSchema Schema = fStore.Schema;
            Schema.Load();
            DbMetaTable[] Tables = Schema.Tables.Where(Item => string.Equals(Item.Name, fListTable.TableName, StringComparison.OrdinalIgnoreCase)).ToArray();
            if (Tables.Length != 1)
                throw new InvalidOperationException($"Expected one database table named '{fListTable.TableName}', found {Tables.Length}.");
            SqlStatementBuilder.BuildSaveSql(fListTable, Tables[0]);
        }
        if (HasDeletes && string.IsNullOrWhiteSpace(fListTable.Sqls.DeleteRowSql))
            throw new InvalidOperationException($"Table '{fListTable.TableName}' has no delete statement.");
        if (HasUpdates && string.IsNullOrWhiteSpace(fListTable.Sqls.UpdateRowSql))
            throw new InvalidOperationException($"Table '{fListTable.TableName}' has no update statement.");
        if (HasInserts && string.IsNullOrWhiteSpace(fListTable.Sqls.InsertRowSql))
            throw new InvalidOperationException($"Table '{fListTable.TableName}' has no insert statement.");
    }
    SqlParams CreateRowParams(DataRow Row, DataRowVersion Version)
    {
        SqlParams Result = new();
        foreach (DataColumn Column in fListTable.Columns)
            Result.Add(Column.ColumnName, Row[Column, Version]);
        return Result;
    }
    static bool IsIntegerType(Type Type) => Type == typeof(int) || Type == typeof(long);

    // ● constructor
    /// <summary>
    /// Creates a table set for the specified store, list table and item table.
    /// SQL generation is disabled unless explicitly requested in the flags.
    /// </summary>
    public TableSet(SqlStore Store, MemTable ListTable, MemTable ItemTable, TableSetFlags Flags = TableSetFlags.None)
    {
        ArgumentNullException.ThrowIfNull(Store);
        ArgumentNullException.ThrowIfNull(ListTable);
        ArgumentNullException.ThrowIfNull(ItemTable);
        fStore = Store;
        fListTable = ListTable;
        fItemTable = ItemTable;
        fFlags = Flags;
    }

    // ● public
    /// <summary>
    /// Replaces the list table contents with the result of the supplied SELECT.
    /// Uses the table's SelectSql when SqlText is empty and returns the row count.
    /// </summary>
    public int ListSelect(string SqlText)
    {
        string Text = string.IsNullOrWhiteSpace(SqlText) ? fListTable.Sqls.SelectSql : SqlText;
        if (string.IsNullOrWhiteSpace(Text))
            return 0;
        fListTable.EventsDisabled = true;
        try
        {
            return fStore.SelectTo(fListTable, Text);
        }
        finally
        {
            fListTable.EventsDisabled = false;
        }
    }
    /// <summary>
    /// Saves changes to the list table in one transaction.
    /// Supports string and provider-generated integer primary keys.
    /// </summary>
    public void ListSave()
    {
        if (fListTable.Rows.Cast<DataRow>().Any(Row => Row.HasVersion(DataRowVersion.Proposed)))
            throw new InvalidOperationException("Finish editing list rows before saving.");
        DataRow[] Deleted = fListTable.Rows.Cast<DataRow>().Where(Row => Row.RowState == DataRowState.Deleted).ToArray();
        DataRow[] Modified = fListTable.Rows.Cast<DataRow>().Where(Row => Row.RowState == DataRowState.Modified).ToArray();
        DataRow[] Added = fListTable.Rows.Cast<DataRow>().Where(Row => Row.RowState == DataRowState.Added).ToArray();
        if (Deleted.Length + Modified.Length + Added.Length == 0)
            return;
        if (fListTable.KeyFields == null || fListTable.KeyFields.Length != 1 || !fListTable.Columns.Contains(fListTable.KeyField))
            throw new InvalidOperationException("ListSave requires a single key field in the list table.");
        DataColumn Key = fListTable.Columns[fListTable.KeyField];
        bool IntegerKey = IsIntegerType(Key.DataType);
        if (Key.DataType != typeof(string) && !IntegerKey)
            throw new NotSupportedException("ListSave requires a string, Int32 or Int64 primary key.");
        OidMode Mode = fStore.OidMode;
        if (IntegerKey && Added.Length > 0 && Mode == OidMode.None)
            throw new NotSupportedException("The provider has no integer identifier generation mode.");
        if (Modified.Any(Row => !Equals(Row[Key, DataRowVersion.Original], Row[Key, DataRowVersion.Current])))
            throw new InvalidOperationException("ListSave cannot change a primary key.");
        PrepareListSaveSql(Deleted.Length > 0, Modified.Length > 0, Added.Length > 0);
        List<(DataRow Row, object Value)> PreviousIds = new();
        using (SqlTransactionContext Context = fStore.BeginTransactionContext())
        {
            try
            {
                foreach (DataRow Row in Deleted)
                {
                    if (fStore.ExecSql(Context.Transaction, fListTable.Sqls.DeleteRowSql, CreateRowParams(Row, DataRowVersion.Original)) == 0)
                        throw new InvalidOperationException($"Delete did not affect a row in table '{fListTable.TableName}'.");
                }
                foreach (DataRow Row in Modified)
                {
                    if (fStore.ExecSql(Context.Transaction, fListTable.Sqls.UpdateRowSql, CreateRowParams(Row, DataRowVersion.Current)) == 0)
                        throw new InvalidOperationException($"Update did not affect a row in table '{fListTable.TableName}'.");
                }
                foreach (DataRow Row in Added)
                {
                    if (IntegerKey)
                    {
                        PreviousIds.Add((Row, Row[Key]));
                        if (Mode == OidMode.Generator)
                            Row[Key] = Convert.ChangeType(fStore.NextId(Context.Transaction, fListTable.TableName), Key.DataType, System.Globalization.CultureInfo.InvariantCulture);
                    }
                    if (fStore.ExecSql(Context.Transaction, fListTable.Sqls.InsertRowSql, CreateRowParams(Row, DataRowVersion.Current)) == 0)
                        throw new InvalidOperationException($"Insert did not affect a row in table '{fListTable.TableName}'.");
                    if (IntegerKey && Mode == OidMode.AutoInc)
                        Row[Key] = Convert.ChangeType(fStore.LastId(Context.Transaction, fListTable.TableName), Key.DataType, System.Globalization.CultureInfo.InvariantCulture);
                }
                Context.Commit();
            }
            catch
            {
                if (Context.IsActive)
                {
                    try
                    {
                        Context.Rollback();
                        for (int Index = PreviousIds.Count - 1; Index >= 0; Index--)
                            PreviousIds[Index].Row[Key] = PreviousIds[Index].Value;
                    }
                    catch
                    {
                        // TODO: Log rollback or identifier restoration failures.
                    }
                }
                throw;
            }
        }
        fListTable.AcceptChanges();
    }
    /// <summary>
    /// Rejects pending changes in the list table.
    /// Detail tables are not affected.
    /// </summary>
    public void ListCancel() => fListTable.RejectChanges();
}
